class Solution {
    public int findTheWinner(int n,int k){
        int winner=0;
        for(int size=1;size<=n;size++)winner=(winner+k)%size;
        return winner+1;
    }
}

code.kotlin:
class Solution {
    fun findTheWinner(n:Int,k:Int):Int{
        var winner=0;
        for(size in 1..n)winner=(winner+k)%size;
        return winner+1
    }
}

